local _, ns = ...
ns.Scorer = (function()
-- Lootomania scorer. Pure Lua 5.1, runs in the build and in the game client.
--
-- score(item, class, spec, weights [, level]) -> number, best suffix index
--   item = {
--     stats     = { statKey = amount },            -- keys from statkeys.lua
--     slot      = "Head" ... "MainHand", "OffHand", "Ranged",
--     armorType = "Cloth" | "Leather" | "Mail" | "Plate" | nil,
--     weapon    = { dps = n, speed = n, hand = "two" | "one" | "main" | "off" | "ranged" },
--     suffixes  = { { stats = {..} } or {..}, ... }, -- random suffix rolls, best one counts
--     procs     = { proc, ... },                    -- see PROC KINDS below
--     relic     = true, ilvl = n,                   -- idols, librams, totems
--   }
--   weights = table written by build/weights/generate.lua

local M = {}

-- Stat key -> weight key, where they differ.
local WEIGHT_KEY = {
	expertise = "weaponSkill",
	skillAxe = "weaponSkill", skillAxe2H = "weaponSkill", skillSword = "weaponSkill", skillSword2H = "weaponSkill",
	skillMace = "weaponSkill", skillMace2H = "weaponSkill", skillDagger = "weaponSkill", skillFist = "weaponSkill",
	skillPolearm = "weaponSkill", skillStaff = "weaponSkill", skillBow = "weaponSkill", skillGun = "weaponSkill",
	skillCrossbow = "weaponSkill", skillThrown = "weaponSkill",
	resArcane = "resist", resFire = "resist", resFrost = "resist", resNature = "resist", resShadow = "resist",
	resHoly = "resist",
}

-- The armour-class multiplier applies to these slots only.
local ARMOR_SLOT = { Head = true, Shoulder = true, Chest = true, Wrist = true, Hands = true, Waist = true, Legs = true, Feet = true }

local DEFAULT_PPM = 2
-- Health gained per minute, in stamina weights. Non-tanks use a 0.35 share of it.
local HEALTH_VALUE = 0.075
local HEALTH_SHARE = 0.35

local cache = setmetatable({}, { __mode = "k" })

-- Keys of a table in sorted order, into a reused list (no garbage per call). Float sums must add
-- in a fixed order: `pairs` order changes between processes (LuaJIT seeds its string hash), and a
-- different order moves a score in its last bit, enough to flip the two-decimal rounding.
local scratch = {}
local function SortedKeys(t)
	local n = 0
	for k in pairs(t) do
		n = n + 1
		scratch[n] = k
	end
	for i = #scratch, n + 1, -1 do scratch[i] = nil end
	table.sort(scratch)
	return scratch, n
end

-- Final weights of one spec: base weights, levelling multipliers, derived weights.
local function effective(rec, weights, level)
	local lv = weights.levelling
	local on = lv and (not level or not lv.untilLevel or level <= lv.untilLevel) and true or false
	local byMode = cache[rec]
	if not byMode then byMode = {}; cache[rec] = byMode end
	local w = byMode[on]
	if w then return w end
	w = {}
	local flags = rec.flags or {}
	local skip = flags.noLevelMult
	for k, v in pairs(rec.weights) do
		local m = on and lv.mult[k] or 1
		if skip and skip[k] then m = 1 end
		w[k] = v * m
	end
	-- Tanks that get armour, dodge and crit from agility.
	local fold = flags.agiFold
	if fold then
		local add = 0
		local keys, n = SortedKeys(fold)
		for i = 1, n do add = add + (w[keys[i]] or 0) * fold[keys[i]] end
		w.agi = (w.agi or 0) + add
	end
	-- Attack power against one creature type is worth a third of plain attack power.
	if w.apVs == nil and w.ap then w.apVs = w.ap / 3 end
	if w.spVs == nil and w.sp then w.spVs = w.sp / 3 end
	byMode[on] = w
	return w
end
M.effective = effective

-- Hit and crit are one stat for melee and spells on Forever: items carry both keys with the same
-- value. The part both keys share counts once, with the higher of the two weights.
local TWINS = { { "hit", "spellHit" }, { "crit", "spellCrit" } }

local function statSum(stats, w)
	local s = 0
	local keys, n = SortedKeys(stats)
	for i = 1, n do
		local k = keys[i]
		local wk = w[WEIGHT_KEY[k] or k]
		if wk then s = s + stats[k] * wk end
	end
	for i = 1, #TWINS do
		local a, b = stats[TWINS[i][1]], stats[TWINS[i][2]]
		if a and b then
			s = s - math.min(a, b) * math.min(w[TWINS[i][1]] or 0, w[TWINS[i][2]] or 0)
		end
	end
	return s
end

-- Spell power and healing.
--   sp counts with the sp weight, heal with the heal weight.
--   A healing-only item also counts a third of its healing as spell power (healAsSp weight).
local function foldSum(stats, w)
	local s = statSum(stats, w)
	local heal = stats.heal
	if heal and heal ~= 0 and not stats.sp and w.healAsSp then
		s = s + heal / 3 * w.healAsSp
	end
	return s
end

-- PROC KINDS
--   { kind = "damage", amount = n, ppm = n }             damage per proc, procs per minute (default 2)
--   { kind = "stat", stat = key, amount = n, uptime = f } stat buff, uptime 0..1
--   { kind = "health", amount = n, ppm = n }             heal, life steal or absorb shield
--   { kind = "points", points = n }                      fixed value set by the pipeline
--   onHit = true : needs weapon swings, worth nothing to a spec with no weapon damage weight
local function procPoints(procs, w, dpsWeight, mitigation)
	local s = 0
	for i = 1, #procs do
		local p = procs[i]
		if p.onHit and dpsWeight <= 0 then
			-- nothing
		elseif p.kind == "health" then
			s = s + (p.amount or 0) * (p.ppm or DEFAULT_PPM) * HEALTH_VALUE * (w.sta or 0) * mitigation
		elseif p.kind == "damage" then
			s = s + (p.amount or 0) * (p.ppm or DEFAULT_PPM) / 60 * dpsWeight
		elseif p.kind == "stat" then
			s = s + (p.amount or 0) * (p.uptime or 1) * (w[WEIGHT_KEY[p.stat] or p.stat] or 0)
		elseif p.kind == "points" then
			s = s + (p.points or 0)
		end
	end
	return s
end

local function round2(x)
	-- %.2f rounds the exact binary value (0.425 is stored just below, so it gives 0.42)
	return tonumber(string.format("%.2f", x))
end

function M.score(item, class, spec, weights, level)
	local cls = weights.classes[class]
	local rec = cls and (cls[spec] or cls.levelling)
	if not rec then return 0 end
	local w = effective(rec, weights, level)

	-- stats and best suffix
	local s = item.stats and foldSum(item.stats, w) or 0
	local best
	local suffixes = item.suffixes
	if suffixes then
		local bestSum
		for i = 1, #suffixes do
			local roll = suffixes[i]
			local merged = roll.stats or roll
			-- a suffix can add spell power to a healing-only item, so fold on the merged stats
			local v
			if item.stats then
				local t = {}
				for k, n in pairs(item.stats) do t[k] = n end
				for k, n in pairs(merged) do if type(n) == "number" then t[k] = (t[k] or 0) + n end end
				v = foldSum(t, w)
			else
				v = foldSum(merged, w)
			end
			if not bestSum or v > bestSum then bestSum = v; best = i end
		end
		if bestSum then s = bestSum end
	end

	-- armour class
	local slot = item.slot
	if item.armorType and ARMOR_SLOT[slot] and rec.armorMult then
		s = s * (rec.armorMult[item.armorType] or 1)
	end

	-- weapon
	local dpsWeight = rec.dps or 0
	local wpn = item.weapon
	if slot == "Ranged" then dpsWeight = rec.dpsRanged or 0 end
	if wpn and wpn.dps then
		s = s + wpn.dps * dpsWeight
		if rec.speed and wpn.speed and slot == "MainHand" then
			s = s + rec.speed * wpn.speed
		end
	end

	if item.procs then s = s + procPoints(item.procs, w, dpsWeight, rec.flags and rec.flags.mitigation or HEALTH_SHARE) end

	-- A relic with no priced stats still beats an empty slot.
	if item.relic and s <= 0 then s = (item.ilvl or 0) * 0.01 end

	return round2(s), best
end

return M

end)()
